lines = content.split(b'\n')
for i, line in enumerate(lines[30:35], start=31):
    print(f"Line {i}: {line}")
    if b'migrat' in line:
        # Print hex representation
        print(f"  Hex: {line.hex()}")
        # Look for the word
        for match in [b'migarting', b'migrating']:
            if match in line:
                idx = line.index(match)
                print(f"  Found {match!r} at position {idx}")
                print(f"  Characters:")
                for j, byte in enumerate(match):
                    print(f"    {j}: {chr(byte)} (0x{byte:02x})")

